        "🛑 Đang yêu cầu dừng quét... Nick hiện tại sẽ được đóng ngay lập tức.": { en: "🛑 Đang yêu cầu dừng quét... accounts hiện tại sẽ được đóng ngay lập tức.", zh: "🛑 Đang yêu cầu dừng quét... 账号 hiện tại sẽ được đóng ngay lập tức." },
        "🟢 Hoạt động": { en: "🟢 Hoạt động", zh: "🟢 Hoạt động" },
        "🤖 Tự Động Chọn Theo Nội Dung": { en: "🤖 Tự Động Select by Nội Dung", zh: "🤖 Tự Động 选择 按照 Nội Dung" },
